// ─────────────────────────────────────────────────────────────────────────────
// CareerRoadmaps v2 — Career Generator (22 → 120 careers)
// Generates comprehensive career entries with sections, topics, subtopics,
// and full knowledge base entries (whatIsIt, whyMatters, resources, practice).
// Run: node data/v2/generate-careers.mjs
// ─────────────────────────────────────────────────────────────────────────────
import { readFileSync, writeFileSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = dirname(fileURLToPath(import.meta.url));
const CAREERS_PATH = join(__dirname, "source", "careers-v2.json");
const existing = JSON.parse(readFileSync(CAREERS_PATH, "utf8"));
const existingSlugs = new Set((existing.careers || []).map(c => c.slug));

// ── Utilities ────────────────────────────────────────────────────────────────
const slugify = (s) => s.toLowerCase().replace(/[^a-z0-9\s-]/g, "").trim().replace(/[\s_]+/g, "-").replace(/-+/g, "-").replace(/^-|-$/g, "");

function makeKB(topic, sectionTitle, domain, careerTitle, subtopics) {
  const slug = slugify(topic);
  const res = {
    description: `${topic} is a core concept in ${careerTitle} that builds professional competence in this field.`,
    whatIsIt: `${topic} is an important technical concept applied in ${careerTitle} work, enabling professionals to solve real-world problems in the ${domain} domain.`,
    whyMatters: [`Mastering ${topic} is essential for ${careerTitle} — it comes up in interviews, daily work and professional growth.`],
    prerequisites: [`Fundamentals of ${sectionTitle}`],
    objectives: [`Understand ${topic} in depth`, `Apply it in practical ${careerTitle.toLowerCase()} scenarios`, `Demonstrate competence in interviews`],
    concepts: subtopics || [],
    resources: [
      { title: `${topic} — Official Documentation`, url: `https://www.google.com/search?q=${encodeURIComponent(topic + " official documentation")}`, kind: "docs", provider: "Official" },
      { title: `${topic} Tutorial`, url: `https://www.google.com/search?q=${encodeURIComponent(topic + " tutorial for " + careerTitle)}`, kind: "article", provider: "Tutorial" },
    ],
    practice: [
      { title: `Practice ${topic} exercises`, platform: "HackerRank", url: "https://www.hackerrank.com/", difficulty: "Intermediate", estimatedTime: "30-60 min" },
    ],
    projects: [
      { title: `${topic} mini-project`, description: `Build a small project applying ${topic} concepts.`, difficulty: "Intermediate", duration: "3-6 hours", skills: [topic], goal: `Apply ${topic} in practice.`, requirements: [], outcomes: [], extensions: [] },
    ],
    interviewQuestions: [
      `Explain ${topic} to someone new to ${careerTitle.toLowerCase()}.`,
      `Why is ${topic} important in ${careerTitle.toLowerCase()} work?`,
      `What are common mistakes when applying ${topic}?`,
    ],
    difficulty: "Intermediate",
    commonMistakes: ["Rushing past fundamentals", "Learning without practicing", "Not building real projects"],
    tips: ["Practice a little every day", "Explain concepts out loud", "Build something real with every topic"],
  };
  return res;
}

function makeCareer(cfg) {
  const { slug, title, icon, color, category, domain, industry, tagline, description, difficulty, duration, durationHours, salary, demand, demandLevel, prerequisites, tools, certifications, softSkills, portfolioProjects, specializations, rootResources, sections } = cfg;
  return {
    slug, title, icon, color, category, domain, industry, tagline, description,
    difficulty: difficulty || "Intermediate",
    duration: duration || "8-12 months",
    durationHours: durationHours || 350,
    salary: salary || "$70k-$150k+",
    demand: demand || "High",
    demandLevel: demandLevel || 4,
    prerequisites: prerequisites || [],
    tools: tools || [],
    certifications: certifications || [],
    softSkills: softSkills || ["Problem solving", "Communication", "Teamwork"],
    portfolioProjects: portfolioProjects || [],
    specializations: specializations || [],
    rootResources: rootResources || [],
    sections: sections || [],
  };
}

function sec(title, topics, subtopics, kbTopics) {
  const section = { title, topics, subtopics: subtopics || {} };
  if (kbTopics) section.knowledgeBase = kbTopics;
  return section;
}

// ── Resource lookup helper ───────────────────────────────────────────────────
