// Merge and Write
// ─────────────────────────────────────────────────────────────────────────────
const allNewCareers = [
  ...softwareCareers,
  ...dataAICareers,
  ...cyberCareers,
  ...cloudInfraCareers,
  ...remainingCareers,
];

let added = 0, skipped = 0;
for (const career of allNewCareers) {
  if (existingSlugs.has(career.slug)) {
    skipped++;
    continue;
  }
  existing.careers.push(career);
  existingSlugs.add(career.slug);
  added++;
}

writeFileSync(CAREERS_PATH, JSON.stringify(existing, null, 2));
console.log(`✓ Career expansion complete`);
console.log(`  Added: ${added} new careers`);
console.log(`  Skipped: ${skipped} (already exist)`);
console.log(`  Total careers: ${existing.careers.length}`);
console.log(`  Written to: ${CAREERS_PATH}`);
